CREATE TABLE IF NOT EXISTS public.rotas_test ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL UNIQUE, ordem int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() ); GRANT SELECT ON public.rotas_test TO authenticated; GRANT ALL ON public.rotas_test TO service_role; ALTER TABLE public.rotas_test ENABLE ROW LEVEL SECURITY; DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'rotas_test' AND policyname = 'Rotas readable') THEN CREATE POLICY "Rotas readable" ON public.rotas_test FOR SELECT TO authenticated USING (true); END IF; END $$; INSERT INTO public.rotas_test (nome, ordem) VALUES ('Rota 1', 1), ('Rota 2', 2) ON CONFLICT (nome) DO NOTHING; DO $$ DECLARE m RECORD; v_bar uuid; v_rota uuid; BEGIN FOR m IN SELECT * FROM (VALUES ('Fundo','Rota 1',6,6),('Meio','Rota 1',6,6)) AS t(nome, rota, ph, pa) LOOP SELECT id INTO v_bar FROM public.bars WHERE btrim(lower(name)) = btrim(lower(m.nome)) LIMIT 1; IF v_bar IS NULL THEN RAISE NOTICE 'BAR NÃO ENCONTRADO: %', m.nome; CONTINUE; END IF; SELECT id INTO v_rota FROM public.rotas_test WHERE nome = m.rota; UPDATE public.bars SET rota_id = v_rota WHERE id = v_bar; INSERT INTO public.bar_stock_standard (bar_id, brand, barris_padrao) VALUES (v_bar, 'heineken', m.ph) ON CONFLICT (bar_id, brand) DO UPDATE SET barris_padrao = EXCLUDED.barris_padrao; END LOOP; END $$;